package org.apache.commons.codec.binary;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.FilterInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.math.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class Base64InputStream_read_TriageGen0Test {

    @Test(expected = NullPointerException.class)
    public void testRead_NullBuffer() throws IOException {
        Base64InputStream bis = new Base64InputStream(new ByteArrayInputStream(new byte[0]));
        bis.read(null, 0, 0);
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testRead_NegativeOffset() throws IOException {
        Base64InputStream bis = new Base64InputStream(new ByteArrayInputStream(new byte[0]));
        bis.read(new byte[10], -1, 5);
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testRead_NegativeLen() throws IOException {
        Base64InputStream bis = new Base64InputStream(new ByteArrayInputStream(new byte[0]));
        bis.read(new byte[10], 0, -1);
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testRead_OffsetGreaterThanLength() throws IOException {
        Base64InputStream bis = new Base64InputStream(new ByteArrayInputStream(new byte[0]));
        bis.read(new byte[10], 11, 0);
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testRead_OffsetPlusLenGreaterThanLength() throws IOException {
        Base64InputStream bis = new Base64InputStream(new ByteArrayInputStream(new byte[0]));
        bis.read(new byte[10], 5, 6);
    }

    @Test
    public void testRead_LenZero() throws IOException {
        Base64InputStream bis = new Base64InputStream(new ByteArrayInputStream(new byte[0]));
        int result = bis.read(new byte[10], 0, 0);
        assertEquals(0, result);
    }

    @Test
    public void testRead_DecodeSuccess() throws IOException {
        // "SGVsbG8=" is "Hello" in Base64
        byte[] input = "SGVsbG8=".getBytes(StandardCharsets.UTF_8);
        Base64InputStream bis = new Base64InputStream(new ByteArrayInputStream(input), false);

        byte[] b = new byte[10];
        int read = bis.read(b, 0, 5);

        assertEquals(5, read);
        assertEquals("Hello", new String(b, 0, 5, StandardCharsets.UTF_8));
    }

    @Test
    public void testRead_EncodeSuccess() throws IOException {
        // "Hello" -> "SGVsbG8="
        byte[] input = "Hello".getBytes(StandardCharsets.UTF_8);
        Base64InputStream bis = new Base64InputStream(new ByteArrayInputStream(input), true);

        byte[] b = new byte[8];
        int read = bis.read(b, 0, 8);

        assertEquals(8, read);
        // Note: The exact output depends on internal padding/buffer, 
        // but we verify it completes without error and returns positive.
    }

    @Test
    public void testRead_SetInitialBufferTrigger() throws IOException {
        // Testing the branch: if (c > 0 && b.length == len)
        // This happens when we read exactly the size of the buffer provided
        byte[] input = "SGVsbG8=".getBytes(StandardCharsets.UTF_8);
        Base64InputStream bis = new Base64InputStream(new ByteArrayInputStream(input), false);

        // Provide a buffer where length == len
        byte[] b = new byte[7];
        int read = bis.read(b, 0, 7);

        assertEquals(7, read);
    }

    @Test
    public void testRead_EndOfStream() throws IOException {
        byte[] input = "SGVsbG8=".getBytes(StandardCharsets.UTF_8);
        Base64InputStream bis = new Base64InputStream(new ByteArrayInputStream(input), false);

        byte[] b = new byte[100];
        bis.read(b, 0, 100);

        // After reading all data, next read should return -1 (via base64.readResults)
        int read = bis.read(b, 0, 10);
        assertEquals(-1, read);
    }

    @Test
    public void testRead_NonBase64Data() throws IOException {
        // Providing non-base64 characters might cause readResults to return 0 in some implementations
        // to trigger the while loop.
        byte[] input = "!!!".getBytes(StandardCharsets.UTF_8);
        Base64InputStream bis = new Base64InputStream(new ByteArrayInputStream(input), false);

        byte[] b = new byte[10];
        int read = bis.read(b, 0, 10);

        // Should handle the loop and eventually return EOF or actual data
        // In this case, no base64 data, so it should return -1 or 0 depending on base64 object
        // But it must not hang.
        if (read != -1) {
            // If it returns something, it's valid
        }
    }
}
